<script setup>
import {computed,ref,watch,nextTick,onMounted,onUnmounted,useId} from 'vue';import {ChevronDown,Upload,Check} from 'lucide-vue-next';import {useStudio} from '../store';import {fontList,loadFonts,ensureFont,importFont} from '../editor/fonts';import {fuzzyMatch} from '../../shared/search.mjs';
const props=defineProps({modelValue:String});const emit=defineEmits(['update:modelValue']);const s=useStudio(),open=ref(false),query=ref(''),group=ref('全部'),anchor=ref(),input=ref(),list=ref(),loading=ref(false),position=ref({}),id='font-'+useId();let observer;
const current=computed(()=>fontList.value.find(item=>item.family===props.modelValue)),groups=['全部','自带','导入','本机'];
const filtered=computed(()=>fontList.value.filter(font=>(group.value==='全部'||font.source===({自带:'bundled',导入:'imported',本机:'system'})[group.value])&&fuzzyMatch(query.value,font.label,font.originalFamily,font.family,font.category)));
onMounted(()=>loadFonts().catch(()=>{}));onUnmounted(()=>observer?.disconnect());
async function observe(){await nextTick();observer?.disconnect();if(!open.value||!list.value)return;observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting)ensureFont(entry.target.dataset.family).catch(()=>{});},{root:list.value});list.value.querySelectorAll('[data-family]').forEach(el=>observer.observe(el));}
watch([open,filtered],observe);
async function toggle(){open.value=!open.value;if(!open.value)return;const r=anchor.value.getBoundingClientRect(),width=Math.min(360,window.innerWidth-24),height=Math.min(370,window.innerHeight-24);position.value={left:Math.max(12,Math.min(r.left,window.innerWidth-width-12))+'px',top:Math.max(12,r.bottom+height>window.innerHeight?r.top-height-5:r.bottom+5)+'px',width:width+'px',maxHeight:height+'px'};try{await loadFonts();}catch{s.notify('字体列表暂时不可用，请刷新后重试','error');}await nextTick();input.value?.focus();}
async function choose(font){try{await ensureFont(font.family);emit('update:modelValue',font.family);open.value=false;}catch{s.notify('字体加载失败，请重新导入有效字体','error');}}
async function add(event){loading.value=true;try{for(const file of event.target.files){const font=await importFont(file);emit('update:modelValue',font.family);}group.value='导入';open.value=true;}catch(error){s.notify(error.message,'error');}finally{loading.value=false;event.target.value='';}}
</script>
<template><div class="font-select"><button ref="anchor" type="button" class="font-select-trigger" role="combobox" aria-label="字体" :aria-expanded="open" :aria-controls="id" aria-haspopup="listbox" @click="toggle"><span :style="{fontFamily:modelValue}">{{current?.label||modelValue||'默认字体'}}</span><ChevronDown :size="15"/></button><input type="file" class="hidden" accept=".ttf,.otf,.woff,.woff2" multiple @change="add"/><Teleport to="body"><template v-if="open"><div class="font-select-dismiss" @pointerdown="open=false"/><section class="font-select-popup" :style="position" @keydown.esc.stop="open=false"><div class="font-select-search"><input ref="input" v-model="query" aria-label="搜索字体" placeholder="搜索中文或英文字体、风格" @keydown.enter.prevent="filtered[0]&&choose(filtered[0])"/></div><div class="font-select-groups"><button v-for="name in groups" type="button" :class="{active:group===name}" @click="group=name">{{name}}</button><button type="button" :disabled="loading" @click="$el.querySelector('input[type=file]').click()"><Upload :size="13"/>{{loading?'导入中':'导入字体'}}</button></div><div ref="list" :id="id" class="font-select-list" role="listbox" aria-label="字体列表"><button v-for="font in filtered" :key="font.id" type="button" role="option" :aria-selected="modelValue===font.family" :data-family="font.family" @click="choose(font)"><span :style="{fontFamily:font.family}">{{font.label}}</span><small>{{font.source==='bundled'?'自带':font.source==='imported'?'导入':'本机'}}</small><Check v-if="modelValue===font.family" :size="13"/></button><p v-if="!filtered.length">没有匹配字体</p></div><footer>{{fontList.length}} 种字体 · 可导入 TTF / OTF / WOFF / WOFF2</footer></section></template></Teleport></div></template>
